Phân tích chương trình sau và cho biết hàm `int mystery2( const char *s )` thực hiện công việc gì:
```cpp
#include <iostream>
using namespace std;

int mystery2( const char * ); // prototype

int main()
{
   char string1[ 80 ];

   cout << "Enter a string: ";
   cin >> string1;
   cout << mystery2( string1 ) << endl;
}

int mystery2( const char *s )
{
   unsigned int x;

   for ( x = 0; *s != '\0'; ++s )
      ++x;

   return x;
}
```

