#include <iostream>
#include <string_view>

// Classic C-style implementation equivalent to mystery1 & mystery2
int custom_strlen(const char* s) {
    int len = 0;
    for (; *s != '\0'; ++s) {
        ++len;
    }
    return len;
}

void custom_strcat(char* dest, const char* src) {
    while (*dest != '\0') {
        ++dest;
    }
    while ((*dest = *src) != '\0') {
        ++dest;
        ++src;
    }
}

int main() {
    char buffer[50] = "Hello";
    const char addition[] = "_Simpletron";

    std::cout << "Initial length: " << custom_strlen(buffer) << "\n";
    custom_strcat(buffer, addition);
    std::cout << "Concatenated: " << buffer << "\n";
    std::cout << "New length: " << custom_strlen(buffer) << "\n";

    // C++17 alternative
    std::string_view sv{buffer};
    std::cout << "Length via std::string_view: " << sv.length() << "\n";
    return 0;
}

