// Demonstrates SML instruction extraction and single arithmetic step
int main() {
    int instruction = 3008; // SML: Add memory location 08
    int memory[100] = {0};

    // Populate sample memory
    memory[8] = 45; // Operand data
    int accumulator = 55;

    int opCode = instruction / 100;
    int operand = instruction % 100;

    std::cout << "Instruction: +" << instruction << "\n";
    std::cout << "Opcode: " << opCode << " (Add)\n";
    std::cout << "Operand: " << operand << "\n";
    std::cout << "Accumulator before: " << accumulator << "\n";

    if (opCode == 30) { // add
        accumulator += memory[operand];
    }

    std::cout << "Accumulator after:  " << accumulator << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>
#include <array>

void dump(int accumulator, int instructionCounter, int instructionRegister,
          int operationCode, int operand, const std::array<int, 100>& memory) {
    std::cout << "\nREGISTERS:\n";
    std::cout << "accumulator:         " << std::showpos << std::internal 
              << std::setw(5) << std::setfill('0') << accumulator << std::noshowpos << "\n";
    std::cout << "instructionCounter:  " << std::setw(2) << std::setfill('0') << instructionCounter << "\n";
    std::cout << "instructionRegister: " << std::showpos << std::internal 
              << std::setw(5) << std::setfill('0') << instructionRegister << std::noshowpos << "\n";
    std::cout << "operationCode:       " << std::setw(2) << std::setfill('0') << operationCode << "\n";
    std::cout << "operand:             " << std::setw(2) << std::setfill('0') << operand << "\n";
}

int main() {
    std::array<int, 100> memory{};
    // SML Program: Load 04, Subtract 05, Halt
    memory[0] = 2004; // load 04
    memory[1] = 3105; // subtract 05
    memory[2] = 4300; // halt
    memory[4] = 120;  // Data A
    memory[5] = 45;   // Data B

    int accumulator = 0;
    int instructionCounter = 0;
    int instructionRegister = 0;
    int operationCode = 0;
    int operand = 0;
    bool running = true;

    while (running && instructionCounter < 100) {
        instructionRegister = memory[instructionCounter];
        operationCode = instructionRegister / 100;
        operand = instructionRegister % 100;
        ++instructionCounter;

        switch (operationCode) {
            case 20: // load
                accumulator = memory[operand];
                break;
            case 31: // subtract
                accumulator -= memory[operand];
                break;
            case 43: // halt
                std::cout << "*** Simpletron execution terminated ***\n";
                running = false;
                break;
            default:
                std::cout << "*** Invalid opcode ***\n";
                running = false;
                break;
        }
    }

    dump(accumulator, instructionCounter, instructionRegister, operationCode, operand, memory);
    return 0;
}
